//! `cargo xtask php-stubs [--update] [--pull]`: the editor's own PHP stubs, generated by running
//! `tools/php-stubs/dump.php` (reflection) on every PHP version listed in
//! `docker/php/compose.yaml`, each in its official Alpine Docker image. The dumps are merged:
//! every function / class / method / constant gets the version it appeared in (and the one
//! it was removed in), with its signature from the newest version that has it.
//!
//! Each version is dumped from an image built on the official one (`docker/php/Dockerfile`)
//! with the extensions PHP ships but doesn't compile in by default ([`BUNDLED`]) and, for
//! the two newest versions, popular PECL extensions ([`PECL`]). Every record carries the
//! extension providing it; PECL ones get no "since" / "removed" (they are installed apart
//! from PHP, so PHP's version says nothing about them).
//!
//! `--update` first asks Docker Hub which PHP releases exist (`X.Y-cli-alpine`) and adds
//! the new ones to `docker/php/compose.yaml`, so a new PHP version needs no manual step;
//! `--pull` downloads missing images.
//!
//! Only developers / CI run this (Docker needed); the result,
//! `crates/modules/languages/php/data/php.stubs`, is committed and embedded in the app, so users
//! need neither PHP nor Docker nor a network connection.

use std::collections::BTreeMap;
use std::path::Path;
use std::process::Command;

/// Extensions PHP ships but its official images don't compile in (installed where they
/// exist for that version).
const BUNDLED: &[&str] = &[
    "bcmath",
    "bz2",
    "calendar",
    "dba",
    "enchant",
    "exif",
    "ffi",
    "gd",
    "gettext",
    "gmp",
    "imap",
    "intl",
    "ldap",
    "mysqli",
    "odbc",
    "opcache",
    "pcntl",
    "pdo_dblib",
    "pdo_mysql",
    "pdo_odbc",
    "pdo_pgsql",
    "pgsql",
    "pspell",
    "shmop",
    "snmp",
    "soap",
    "sockets",
    "sodium",
    "sysvmsg",
    "sysvsem",
    "sysvshm",
    "tidy",
    "xmlrpc",
    "xsl",
    "zip",
];

/// Popular PECL extensions (installed on the two newest PHP versions).
const PECL: &[&str] = &[
    "amqp",
    "apcu",
    "ast",
    "ds",
    "event",
    "http",
    "igbinary",
    "imagick",
    "mailparse",
    "memcached",
    "mongodb",
    "msgpack",
    "oauth",
    "pcov",
    "raphf",
    "rdkafka",
    "redis",
    "ssh2",
    "swoole",
    "uuid",
    "xdebug",
    "yaml",
    "zstd",
];

pub fn generate(root: &Path, update: bool, pull: bool) -> Result<String, String> {
    let tools = root.join("tools").join("php-stubs");
    let compose = root.join("docker").join("php").join("compose.yaml");
    if update {
        let added = add_new_versions(&compose)?;
        if !added.is_empty() {
            eprintln!("php-stubs: new PHP versions: {}", added.join(", "));
        }
    }
    let list =
        std::fs::read_to_string(&compose).map_err(|e| format!("{}: {e}", compose.display()))?;
    // The images, in file order: `image: php:<version>-cli-alpine`.
    let versions: Vec<(String, String)> = list
        .lines()
        .filter_map(|l| l.trim().strip_prefix("image:"))
        .map(str::trim)
        .filter_map(|image| {
            let version = image.strip_prefix("php:")?.split('-').next()?;
            Some((version.to_owned(), image.to_owned()))
        })
        .collect();
    if versions.is_empty() {
        return Err(format!("no PHP images in {}", compose.display()));
    }
    if !pull {
        let missing: Vec<&str> = versions
            .iter()
            .filter(|(_, image)| !has_image(image))
            .map(|(_, i)| i.as_str())
            .collect();
        if !missing.is_empty() {
            return Err(format!(
                "missing Docker images: {} (run with --pull to download them)",
                missing.join(", ")
            ));
        }
    }
    // Record key (kind and name, without the signature) → (first, last version index,
    // the record from the newest version).
    let mut records: BTreeMap<String, (usize, usize, String)> = BTreeMap::new();
    let dockerfile = root.join("docker").join("php");
    for (i, (version, image)) in versions.iter().enumerate() {
        eprintln!("php-stubs: {version} ({image})");
        let with_pecl = i + 2 >= versions.len();
        let image = extended_image(&dockerfile, version, with_pecl, pull)?;
        let dump = dump(&tools, &image)?;
        for line in dump.lines() {
            let Some(key) = key(line) else { continue };
            let entry = records.entry(key).or_insert((i, i, String::new()));
            entry.1 = i;
            entry.2 = line.to_owned();
        }
        let _ = version;
    }
    let last = versions.len() - 1;
    let mut out = String::new();
    out.push_str("# The editor's PHP stubs, generated by `cargo xtask php-stubs` (do not edit).\n");
    out.push_str(
        "# since<TAB>removed<TAB>record; records as written by tools/php-stubs/dump.php.\n",
    );
    let names: Vec<&str> = versions.iter().map(|(v, _)| v.as_str()).collect();
    out.push_str(&format!("v\t{}\n", names.join(",")));
    // A class's extension, for its methods and constants (their records don't name it).
    let class_extension: std::collections::HashMap<String, String> = records
        .values()
        .filter(|(_, _, l)| l.starts_with("c\t"))
        .filter_map(|(_, _, l)| {
            Some((l.split('\t').nth(2)?.to_ascii_lowercase(), extension(l).to_owned()))
        })
        .collect();
    let function_extension: std::collections::HashMap<String, String> = records
        .values()
        .filter(|(_, _, l)| l.starts_with("f\t"))
        .filter_map(|(_, _, l)| {
            Some((l.split('\t').nth(1)?.to_ascii_lowercase(), extension(l).to_owned()))
        })
        .collect();
    for (first, seen_last, line) in records.values() {
        // PECL: installed apart from PHP, so no "since" / "removed".
        let owner = match line.split('\t').next() {
            Some("m" | "cc" | "dm" | "p") => line.split('\t').nth(1).map(str::to_ascii_lowercase),
            _ => None,
        };
        // A deprecated function's extension: its function's.
        let function = match line.split('\t').next() {
            Some("df") => line.split('\t').nth(1).map(str::to_ascii_lowercase),
            _ => None,
        };
        let ext = owner
            .and_then(|o| class_extension.get(&o).cloned())
            .or_else(|| function.and_then(|f| function_extension.get(&f).cloned()))
            .unwrap_or_else(|| extension(line).to_owned());
        let pecl = PECL.contains(&ext.as_str());
        let since = if pecl { &versions[0].0 } else { &versions[*first].0 };
        // Gone after `seen_last`: removed in the next version.
        let removed =
            if *seen_last < last && !pecl { versions[seen_last + 1].0.as_str() } else { "" };
        out.push_str(&format!("{since}\t{removed}\t{line}\n"));
    }
    let target = root.join("crates").join("modules").join("languages").join("php").join("data");
    std::fs::create_dir_all(&target).map_err(|e| e.to_string())?;
    let file = target.join("php.stubs");
    std::fs::write(&file, out).map_err(|e| e.to_string())?;
    Ok(format!("{} records → {}", records.len(), file.display()))
}

fn has_image(image: &str) -> bool {
    Command::new("docker")
        .args(["image", "inspect", image])
        .output()
        .is_ok_and(|o| o.status.success())
}

/// The image with extensions for PHP `version` (`php-stubs:<version>[-pecl]`), built
/// from `docker/php/Dockerfile` if missing (or rebuilt with `--pull`).
fn extended_image(dir: &Path, version: &str, pecl: bool, rebuild: bool) -> Result<String, String> {
    let tag = format!("php-stubs:{version}{}", if pecl { "-pecl" } else { "" });
    if has_image(&tag) && !rebuild {
        return Ok(tag);
    }
    let mut extensions: Vec<&str> = BUNDLED.to_vec();
    if pecl {
        extensions.extend_from_slice(PECL);
    }
    eprintln!("php-stubs: building {tag} ({} extensions)", extensions.len());
    let status = Command::new("docker")
        .args(["build", "-q", "-t", &tag])
        .arg("--build-arg")
        .arg(format!("PHP={version}"))
        .arg("--build-arg")
        .arg(format!("EXTENSIONS={}", extensions.join(" ")))
        .arg(dir)
        .status()
        .map_err(|e| format!("docker build: {e}"))?;
    if !status.success() {
        return Err(format!("docker build failed for {tag}"));
    }
    Ok(tag)
}

/// The extension a dump record names (its last field for `f`, `c`, `k`).
fn extension(line: &str) -> &str {
    let fields: Vec<&str> = line.split('\t').collect();
    match fields.first().copied() {
        Some("f") => fields.get(4).copied().unwrap_or("core"),
        Some("c") => fields.get(5).copied().unwrap_or("core"),
        Some("k") => fields.get(2).copied().unwrap_or("core"),
        _ => "core",
    }
}

/// Runs the dump script in `image` (with the image's php.ini: its extensions loaded).
fn dump(tools: &Path, image: &str) -> Result<String, String> {
    let mount = format!("{}:/stubs:ro", tools.display());
    let output = Command::new("docker")
        .args(["run", "--rm", "-v", &mount, image, "php", "/stubs/dump.php"])
        .output()
        .map_err(|e| format!("docker: {e}"))?;
    if !output.status.success() {
        return Err(format!("{image}: {}", String::from_utf8_lossy(&output.stderr)));
    }
    String::from_utf8(output.stdout).map_err(|e| e.to_string())
}

/// What identifies a record across versions: its kind and name(s), not its signature.
fn key(line: &str) -> Option<String> {
    let fields: Vec<&str> = line.split('\t').collect();
    match fields.first().copied()? {
        "f" | "k" | "df" => Some(format!("{}\t{}", fields[0], fields.get(1)?.to_ascii_lowercase())),
        "c" => Some(format!("c\t{}", fields.get(2)?.to_ascii_lowercase())),
        "m" | "cc" | "dm" | "p" => Some(format!(
            "{}\t{}\t{}",
            fields[0],
            fields.get(1)?.to_ascii_lowercase(),
            fields.get(2)?.to_ascii_lowercase()
        )),
        _ => None,
    }
}

/// `"8.5"` → `(8, 5)`.
fn version_key(v: &str) -> (u32, u32) {
    let mut p = v.split('.').map(|n| n.parse::<u32>().unwrap_or(0));
    (p.next().unwrap_or(0), p.next().unwrap_or(0))
}

/// Whether Docker Hub has the Alpine CLI image of PHP `version` (one small request).
fn hub_has(version: &str) -> Result<bool, String> {
    let url =
        format!("https://hub.docker.com/v2/repositories/library/php/tags/{version}-cli-alpine");
    let output = Command::new("curl")
        .args(["-sS", "-o", "/dev/null", "-w", "%{http_code}", "--max-time", "30", &url])
        .output()
        .map_err(|e| format!("curl: {e}"))?;
    match String::from_utf8_lossy(&output.stdout).trim() {
        "200" => Ok(true),
        "404" => Ok(false),
        code => Err(format!("Docker Hub answered {code} for {version}")),
    }
}

/// The PHP releases after `newest` that have an Alpine CLI image: the next minors of the
/// same major (8.6, 8.7…), then the next majors (9.0, 9.1…).
fn hub_versions_after(newest: (u32, u32)) -> Result<Vec<String>, String> {
    let mut found = Vec::new();
    let (mut major, mut minor) = (newest.0, newest.1 + 1);
    loop {
        let version = format!("{major}.{minor}");
        if hub_has(&version)? {
            found.push(version);
            minor += 1;
        } else if minor > 0 {
            // No more minors: the next major starts at .0.
            major += 1;
            minor = 0;
        } else {
            return Ok(found);
        }
    }
}

/// Adds the PHP releases newer than the newest in `compose` (as Alpine services, like the
/// others). Returns the added versions.
fn add_new_versions(compose: &Path) -> Result<Vec<String>, String> {
    let text = std::fs::read_to_string(compose).map_err(|e| e.to_string())?;
    let newest = text
        .lines()
        .filter_map(|l| l.trim().strip_prefix("image: php:"))
        .filter_map(|image| image.split('-').next())
        .map(version_key)
        .max()
        .unwrap_or((0, 0));
    let added = hub_versions_after(newest)?;
    if added.is_empty() {
        return Ok(added);
    }
    let mut text = text;
    if !text.ends_with('\n') {
        text.push('\n');
    }
    for version in &added {
        text.push_str(&format!(
            "  php{}:\n    image: php:{version}-cli-alpine\n    volumes:\n      - ../../tools/php-stubs:/stubs:ro\n    command: [\"php\", \"-n\", \"/stubs/dump.php\"]\n",
            version.replace('.', "")
        ));
    }
    std::fs::write(compose, text).map_err(|e| e.to_string())?;
    Ok(added)
}

